import os,re
R="D:/repository/"
def scan(root, pat, exts=(".vue",".js",".ts",".scss",".css")):
    n=0;sample=""
    for dp,dn,fn in os.walk(root):
        dn[:]=[d for d in dn if d not in ('node_modules','.git','dist','test-results')]
        for f in fn:
            if not f.endswith(exts): continue
            fp=os.path.join(dp,f)
            try:t=open(fp,encoding='utf-8',errors='ignore').read()
            except:continue
            m=re.search(pat,t)
            if m: n+=1; sample=fp.replace(R,'')+" :: "+t[max(0,m.start()-30):m.end()+50].replace('\n',' ')
    print("scan",root.replace(R,''),pat,"=",n,"|",sample[:150])

